const CODE_GRAPH_CLI_B64 =
  '';

/** Decoded UTF-8 source of the code-graph CLI written into each broker project. */
export function codeGraphCliSource(): string {
  const bin = atob(CODE_GRAPH_CLI_B64);
  const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
  return new TextDecoder('utf-8').decode(bytes);
}
